def canPartitionBlocks(nums):
    n = len(nums)
    ok = [False] * (n + 1)
    ok[0] = True
    for i in range(2, n + 1):
        a = nums[i - 1]
        b = nums[i - 2]
        if ok[i - 2] and a == b:
            ok[i] = True
        elif i >= 3 and ok[i - 3]:
            c = nums[i - 3]
            if (a == b == c) or (b == c + 1 and a == b + 1):
                ok[i] = True
    return ok[n]
